import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-javascript-pluck-values-from-array-of-objects":{"intro":"In this lab, we will be working on a JavaScript programming exercise that involves extracting values from an array of objects. Specifically, we will be writing a function that takes in an array of objects and a key and returns an array of values corresponding to that key. This exercise will help improve your understanding of functional programming concepts and array manipulation in JavaScript.","steps":[{"title":"Pluck Values From Array of Objects","body":["Instructions to Pluck Values From an Array of Objects","To pluck values from an array of objects, you can follow these steps:","• Test the function with an example array of objects:","This will return an array of values corresponding to the specified key from the array of objects."],"code":[{"lang":"js","text":"const pluck = (arr, key) => arr.map((i) => i[key]);"},{"lang":"js","text":"const simpsons = [\n  { name: \"lisa\", age: 8 },\n  { name: \"homer\", age: 36 },\n  { name: \"marge\", age: 34 },\n  { name: \"bart\", age: 10 }\n];\npluck(simpsons, \"age\"); // [8, 36, 34, 10]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const simpsons = [\n  { name: \"lisa\", age: 8 },\n  { name: \"homer\", age: 36 },\n  { name: \"marge\", age: 34 },\n  { name: \"bart\", age: 10 }\n];\npluck(simpsons, \"age\"); // [8, 36, 34, 10]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-generating-powerset-with-javascript":{"intro":"In this lab, we will explore the concept of powerset in JavaScript. You will learn how to create a function that generates all possible combinations of a given array of numbers, including the empty set. By using the Array.prototype.reduce() and Array.prototype.map() methods, you will be able to create a powerful tool that can be used in various scenarios. Join us in this lab to enhance your JavaScript skills and become more proficient in solving complex problems.","steps":[{"title":"Powerset","body":["How to Generate Powerset in JavaScript","To generate a powerset of a given array of numbers in JavaScript, follow these steps:","• To generate the powerset, call the function powerset() and pass in the array as an argument. For example:","This will return an array containing all possible subsets of the given array."],"code":[{"lang":"js","text":"const powerset = (arr) =>\n  arr.reduce((a, v) => a.concat(a.map((r) => r.concat(v))), [[]]);"},{"lang":"js","text":"powerset([1, 2]); // [[], [1], [2], [1, 2]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"powerset([1, 2]); // [[], [1], [2], [1, 2]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-pretty-print-number-of-bytes":{"intro":"In this lab, we will explore the concept of pretty-printing numbers in bytes to a human-readable format using JavaScript. We will learn how to convert a given number of bytes into KB, MB, GB, TB, PB, EB, ZB, and YB by using an array dictionary of units. with the help of the Number.prototype.toPrecision() method, we will truncate the number to a certain number of digits and build a prettified string to display the result.","steps":[{"title":"Pretty-Print Number of Bytes","body":["Convert Bytes to Human-Readable String","To convert a number in bytes to a human-readable string, use the prettyBytes() function. Here are some things to keep in mind:","• The function uses an array dictionary of units to be accessed based on the exponent. • You can use the second argument, precision, to truncate the number to a certain number of digits. The default value is 3. • You can use the third argument, addSpace, to add space between the number and unit. The default value is true. • The function returns the prettified string by building it up, taking into account the supplied options and whether it is negative or not.","Here's the code for the prettyBytes() function:"],"code":[{"lang":"js","text":"const prettyBytes = (num, precision = 3, addSpace = true) => {\n  const UNITS = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\", \"PB\", \"EB\", \"ZB\", \"YB\"];\n  if (Math.abs(num) < 1) return num + (addSpace ? \" \" : \"\") + UNITS[0];\n  const exponent = Math.min(\n    Math.floor(Math.log10(num < 0 ? -num : num) / 3),\n    UNITS.length - 1\n  );\n  const n = Number(\n    ((num < 0 ? -num : num) / 1000 ** exponent).toPrecision(precision)\n  );\n  return (num < 0 ? \"-\" : \"\") + n + (addSpace ? \" \" : \"\") + UNITS[exponent];\n};"},{"lang":"js","text":"prettyBytes(1000); // '1 KB'\nprettyBytes(-27145424323.5821, 5); // '-27.145 GB'\nprettyBytes(123456789, 3, false); // '123MB'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"prettyBytes(1000); // '1 KB'\nprettyBytes(-27145424323.5821, 5); // '-27.145 GB'\nprettyBytes(123456789, 3, false); // '123MB'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-primes-up-to-given-number":{"intro":"In this lab, we will delve into the fascinating world of JavaScript programming. This lab is designed to help you gain practical experience in solving programming problems using JavaScript. You will learn how to generate primes up to a given number using the Sieve of Eratosthenes algorithm.","steps":[{"title":"Primes Up to Given Number","body":["Generating Primes Using Sieve of Eratosthenes","To generate primes up to a given number using the Sieve of Eratosthenes, follow these steps:","Here's the JavaScript code to generate primes up to a given number:","You can call the function generatePrimes() by passing the desired number as an argument. For example:"],"code":[{"lang":"js","text":"const generatePrimes = (num) => {\n  let arr = Array.from({ length: num - 1 }).map((x, i) => i + 2),\n    sqrt = Math.floor(Math.sqrt(num)),\n    numsTillSqrt = Array.from({ length: sqrt - 1 }).map((x, i) => i + 2);\n  numsTillSqrt.forEach(\n    (x) => (arr = arr.filter((y) => y % x !== 0 || y === x))\n  );\n  return arr;\n};"},{"lang":"js","text":"generatePrimes(10); // [2, 3, 5, 7]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"generatePrimes(10); // [2, 3, 5, 7]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-product-of-numeric-values":{"intro":"In this lab, we will be exploring how to calculate the product of two or more numbers/arrays using JavaScript. We will make use of the Array.prototype.reduce() method to multiply each value with an accumulator, which is initialized with a value of 1. By the end of this lab, you will have a better understanding of how to use the reduce method to solve problems involving multiplication of values.","steps":[{"title":"Product of Numeric Values","body":["How to Calculate the Product of Numeric Values in JavaScript","To calculate the product of two or more numbers or arrays in JavaScript, follow these steps:","Here's an example of how to use the prod function:","In the above example, prod(1, 2, 3, 4) and prod(...[1, 2, 3, 4]) both return 24."],"code":[{"lang":"js","text":"const prod = (...arr) => [...arr].reduce((acc, val) => acc * val, 1);\n\nprod(1, 2, 3, 4); // 24\nprod(...[1, 2, 3, 4]); // 24"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const prod = (...arr) => [...arr].reduce((acc, val) => acc * val, 1);\n\nprod(1, 2, 3, 4); // 24\nprod(...[1, 2, 3, 4]); // 24"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-asynchronous-functions-to-promises":{"intro":"In this lab, we will learn how to convert an asynchronous function to return a promise using the promisify function. This will allow us to write cleaner and more readable code by avoiding callback functions. We will also explore the use of currying and the rest operator in JavaScript.","steps":[{"title":"Promisify Function","body":["To convert an asynchronous function to return a promise, follow these steps:","• To use this function, define the asynchronous function and pass it as a parameter to the promisify function. The returned function will now return a promise.","The delay function is an example of an asynchronous function that now returns a promise using the promisify function."],"code":[{"lang":"js","text":"const promisify =\n  (func) =>\n  (...args) =>\n    new Promise((resolve, reject) =>\n      func(...args, (err, result) => (err ? reject(err) : resolve(result)))\n    );"},{"lang":"js","text":"const delay = promisify((d, cb) => setTimeout(cb, d));\ndelay(2000).then(() => console.log(\"Hi!\")); // Promise resolves after 2s"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const delay = promisify((d, cb) => setTimeout(cb, d));\ndelay(2000).then(() => console.log(\"Hi!\")); // Promise resolves after 2s"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-pull-matching-values-from-array":{"intro":"In this lab, we will explore how to pull matching values from an array and return the removed elements. We will learn how to use the Array.prototype.filter(), Array.prototype.includes(), and Array.prototype.push() methods to filter out the values specified in the pull array and mutate the original array. By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Pull Matching Values From Array","body":["How to Pull Matching Values From an Array","To pull out specific values from an array using JavaScript, follow these steps:","Here's an example function that implements these steps:","You can use this function to remove specific values from an array and return the removed elements like this:"],"code":[{"lang":"js","text":"const pullAtValue = (arr, pullArr) => {\n  let removed = [],\n    pushToRemove = arr.forEach((v, i) =>\n      pullArr.includes(v) ? removed.push(v) : v\n    ),\n    mutateTo = arr.filter((v, i) => !pullArr.includes(v));\n  arr.length = 0;\n  mutateTo.forEach((v) => arr.push(v));\n  return removed;\n};"},{"lang":"js","text":"let myArray = [\"a\", \"b\", \"c\", \"d\"];\nlet pulled = pullAtValue(myArray, [\"b\", \"d\"]);\n// myArray = [ 'a', 'c' ] , pulled = [ 'b', 'd' ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"let myArray = [\"a\", \"b\", \"c\", \"d\"];\nlet pulled = pullAtValue(myArray, [\"b\", \"d\"]);\n// myArray = [ 'a', 'c' ] , pulled = [ 'b', 'd' ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-pull-values-from-array-at-index":{"intro":"In this lab, we will explore how to pull values from an array at specific indexes using JavaScript. We will be using the pullAtIndex() function, which mutates the original array to filter out the values at the specified indexes and returns the removed elements. By the end of this lab, you will have a solid understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Pull Values From Array at Index","body":["How to Pull Values From Array at Index","To pull out specific values from an array at certain indexes, follow these steps:"],"code":[{"lang":"js","text":"const pullAtIndex = (arr, pullArr) => {\n  let removed = [];\n  let pulled = arr\n    .map((v, i) => (pullArr.includes(i) ? removed.push(v) : v))\n    .filter((v, i) => !pullArr.includes(i));\n  arr.length = 0;\n  pulled.forEach((v) => arr.push(v));\n  return removed;\n};\n\nlet myArray = [\"a\", \"b\", \"c\", \"d\"];\nlet pulled = pullAtIndex(myArray, [1, 3]);\n// myArray = [ 'a', 'c' ] , pulled = [ 'b', 'd' ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const pullAtIndex = (arr, pullArr) => {\n  let removed = [];\n  let pulled = arr\n    .map((v, i) => (pullArr.includes(i) ? removed.push(v) : v))\n    .filter((v, i) => !pullArr.includes(i));\n  arr.length = 0;\n  pulled.forEach((v) => arr.push(v));\n  return removed;\n};\n\nlet myArray = [\"a\", \"b\", \"c\", \"d\"];\nlet pulled = pullAtIndex(myArray, [1, 3]);\n// myArray = [ 'a', 'c' ] , pulled = [ 'b', 'd' ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-pull-values-from-array-based-on-function":{"intro":"In this lab, we will be exploring the pullBy() function in JavaScript. This function allows us to filter out specific values from an array based on a given iterator function. By the end of this lab, you will understand how to use pullBy() to manipulate arrays and effectively filter out unwanted values.","steps":[{"title":"Pull Values From Array Based on Function","body":["How to Pull Values from an Array based on a Given Function","The function pullBy mutates the original array by filtering out the specified values based on a given iterator function. Here's how it works:","• Check if the last argument provided is a function. • Use Array.prototype.map() to apply the iterator function fn to all array elements. • Use Array.prototype.filter() and Array.prototype.includes() to pull out the values that are not needed. • Set Array.prototype.length to reset the passed-in array's length to 0. • Use Array.prototype.push() to re-populate it with only the pulled values.","And here's an example of how to use it:"],"code":[{"lang":"js","text":"const pullBy = (arr, ...args) => {\n  const length = args.length;\n  let fn = length > 1 ? args[length - 1] : undefined;\n  fn = typeof fn == \"function\" ? (args.pop(), fn) : undefined;\n  let argState = (Array.isArray(args[0]) ? args[0] : args).map((val) =>\n    fn(val)\n  );\n  let pulled = arr.filter((v, i) => !argState.includes(fn(v)));\n  arr.length = 0;\n  pulled.forEach((v) => arr.push(v));\n};"},{"lang":"js","text":"var myArray = [{ x: 1 }, { x: 2 }, { x: 3 }, { x: 1 }];\npullBy(myArray, [{ x: 1 }, { x: 3 }], (o) => o.x); // myArray = [{ x: 2 }]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"var myArray = [{ x: 1 }, { x: 2 }, { x: 3 }, { x: 1 }];\npullBy(myArray, [{ x: 1 }, { x: 3 }], (o) => o.x); // myArray = [{ x: 2 }]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-quarter-of-year":{"intro":"In this lab, we will be exploring the concept of date and time manipulation in JavaScript. We will be focusing on a specific function, quarterOfYear, which takes in a date and returns the quarter and year to which the date belongs. By the end of the lab, you will have a solid understanding of how to extract and manipulate date and time information in JavaScript.","steps":[{"title":"Quarter of Year","body":["Function to Determine Quarter of Year","To determine the quarter of the year, use the quarterOfYear() function. This function takes an optional date argument and returns an array with the quarter and year to which the supplied date belongs.","The quarterOfYear() function uses the following steps to calculate the quarter and year:","• Uses Date.prototype.getMonth() to get the current month in the range (0, 11), adds 1 to map it to the range (1, 12). • Uses Math.ceil() and divides the month by 3 to get the current quarter. • Uses Date.prototype.getFullYear() to get the year from the given date. • Omits the argument, date, to use the current date by default."],"code":[{"lang":"js","text":"const quarterOfYear = (date = new Date()) => [\n  Math.ceil((date.getMonth() + 1) / 3),\n  date.getFullYear()\n];"},{"lang":"js","text":"quarterOfYear(new Date(\"07/10/2018\")); // [ 3, 2018 ]\nquarterOfYear(); // [ 4, 2020 ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"quarterOfYear(new Date(\"07/10/2018\")); // [ 3, 2018 ]\nquarterOfYear(); // [ 4, 2020 ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-query-string-to-object":{"intro":"In this lab, we will explore how to convert a query string or URL into an object using JavaScript. We will use the String.prototype.split() method to extract the parameters from the URL, then create an object using the URLSearchParams constructor and convert it into an array of key-value pairs. Finally, we will use Array.prototype.reduce() to convert the array into a JavaScript object. This lab will help you understand how to manipulate and extract data from URLs and query strings in JavaScript.","steps":[{"title":"Query String to Object","body":["Converting Query String to Object","To convert a query string or URL to an object, follow these steps:","Here is the code to convert the query string:"],"code":[{"lang":"js","text":"const queryStringToObject = (url) =>\n  [...new URLSearchParams(url.split(\"?\")[1])].reduce(\n    (a, [k, v]) => ((a[k] = v), a),\n    {}\n  );"},{"lang":"js","text":"queryStringToObject(\"https://google.com?page=1&count=10\");\n// {page: '1', count: '10'}"}]}],"commands":[],"reference":[{"path":"reference.js","text":"queryStringToObject(\"https://google.com?page=1&count=10\");\n// {page: '1', count: '10'}"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-exploring-javascript-fundamentals-through-ex":{"intro":"In this lab, we will explore the fundamentals of JavaScript programming. Through a series of exercises and challenges, we will cover topics such as variables, data types, functions, control flow, and more. By the end of this lab, you will have a solid understanding of JavaScript syntax and be able to write basic programs in this versatile programming language.","steps":[{"title":"Quick Sort","body":["• Use recursion. • Use the spread operator (...) to clone the original array, arr. • If the length of the array is less than 2, return the cloned array. • Use Math.floor() to calculate the index of the pivot element. • Use Array.prototype.reduce() and Array.prototype.push() to split the array into two subarrays. The first one contains elements smaller than or equal to pivot, and the second one contains elements greater than it. Destructure the result into two arrays. • Recursively call quickSort() on the created subarrays.","Here is an example of how to implement this algorithm:","To test it out, run the following command:"],"code":[{"lang":"js","text":"const quickSort = (arr) => {\n  const a = [...arr];\n  if (a.length < 2) return a;\n  const pivotIndex = Math.floor(arr.length / 2);\n  const pivot = a[pivotIndex];\n  const [lo, hi] = a.reduce(\n    (acc, val, i) => {\n      if (val < pivot || (val === pivot && i != pivotIndex)) {\n        acc[0].push(val);\n      } else if (val > pivot) {\n        acc[1].push(val);\n      }\n      return acc;\n    },\n    [[], []]\n  );\n  return [...quickSort(lo), pivot, ...quickSort(hi)];\n};"},{"lang":"js","text":"quickSort([1, 6, 1, 5, 3, 2, 1, 4]); // [1, 1, 1, 2, 3, 4, 5, 6]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"quickSort([1, 6, 1, 5, 3, 2, 1, 4]); // [1, 1, 1, 2, 3, 4, 5, 6]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-alphanumeric-string":{"intro":"In this lab, we will explore the topic of generating random alphanumeric strings using JavaScript. We will learn how to create a function that generates a random string of a specified length by utilizing various JavaScript methods, such as Array.from(), Math.random(), Number.prototype.toString(), and String.prototype.slice(). By the end of this lab, you will have a better understanding of how to generate random strings in JavaScript and how to use these methods to build more complex applications.","steps":[{"title":"Random Alphanumeric String","body":["How to Generate a Random Alphanumeric String in JavaScript","To generate a random string of alphanumeric characters in JavaScript, follow these steps:","You can call the randomAlphaNumeric() function with the desired length as the argument. For example:"],"code":[{"lang":"js","text":"const randomAlphaNumeric = (length) => {\n  let s = \"\";\n  Array.from({ length }).some(() => {\n    s += Math.random().toString(36).slice(2);\n    return s.length >= length;\n  });\n  return s.slice(0, length);\n};"},{"lang":"js","text":"randomAlphaNumeric(5); // '0afad'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomAlphaNumeric(5); // '0afad'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-boolean-value":{"intro":"In this lab, we will be exploring JavaScript programming by working on various exercises and challenges. Through this lab, you will have the opportunity to apply your knowledge of JavaScript by completing different tasks that will test your understanding of different concepts such as loops, arrays, functions, and more. By the end of the lab, you will have gained a deeper understanding of JavaScript programming and be better equipped to tackle more complex problems in the future.","steps":[{"title":"Random Boolean Value","body":["How to Generate a Random Boolean Value in JavaScript","To generate a random boolean value in JavaScript, follow these steps:","Here's a concise implementation of the code:","You can test the function by calling randomBoolean() which will return either true or false."],"code":[{"lang":"js","text":"const randomBoolean = () => Math.random() >= 0.5;"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const randomBoolean = () => Math.random() >= 0.5;"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-generate-gaussian-random-numbers":{"intro":"In this lab, we will explore how to generate Gaussian random numbers using the Box-Muller transform in JavaScript. The purpose of this lab is to provide a hands-on experience in understanding and implementing a commonly used technique for generating normally distributed random numbers. By the end of this lab, you will have a better understanding of how to generate Gaussian random numbers and how they can be used in various applications.","steps":[{"title":"Generate Gaussian Random Numbers","body":["Generating Gaussian Random Numbers using Box-Muller Transform","To generate Gaussian (normally distributed) random numbers using Box-Muller transform, follow these steps:"],"code":[{"lang":"js","text":"const randomGauss = () => {\n  const theta = 2 * Math.PI * Math.random();\n  const rho = Math.sqrt(-2 * Math.log(1 - Math.random()));\n  return (rho * Math.cos(theta)) / 10.0 + 0.5;\n};"},{"lang":"js","text":"randomGauss(); // 0.5"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomGauss(); // 0.5"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-hex-color-code":{"intro":"In this lab, we will explore the basics of JavaScript programming language. The purpose of this lab is to provide a hands-on experience for beginners in JavaScript to learn and understand the fundamentals of programming concepts such as variables, data types, operators, and control statements. By the end of this lab, you will have a solid foundation in JavaScript programming and be able to create simple programs on your own.","steps":[{"title":"Random Hex Color Code","body":["• To generate a random hex color code, call the function randomHexColorCode().","This will generate a random hex color code that you can use in your coding projects."],"code":[{"lang":"js","text":"const randomHexColorCode = () => {\n  let n = (Math.random() * 0xfffff * 1000000).toString(16);\n  return \"#\" + n.slice(0, 6);\n};"},{"lang":"js","text":"randomHexColorCode(); // '#e34155'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomHexColorCode(); // '#e34155'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-integer-array-in-range":{"intro":"In this lab, we will explore how to generate a random integer array within a specified range using JavaScript. We will use the Array.from() method to create an empty array and fill it with randomly generated integers using Math.random() and Math.floor(). By the end of this lab, you will have a solid understanding of how to generate random integers in JavaScript and apply this knowledge to your own projects.","steps":[{"title":"Random Integer Array in Range","body":["Generating a Random Integer Array in a Specific Range","To generate an array of random integers within a specific range, follow these steps:"],"code":[{"lang":"js","text":"const randomIntArrayInRange = (min, max, n = 1) =>\n  Array.from(\n    { length: n },\n    () => Math.floor(Math.random() * (max - min + 1)) + min\n  );"},{"lang":"js","text":"randomIntArrayInRange(12, 35, 10); // [ 34, 14, 27, 17, 30, 27, 20, 26, 21, 14 ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomIntArrayInRange(12, 35, 10); // [ 34, 14, 27, 17, 30, 27, 20, 26, 21, 14 ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-integer-in-range":{"intro":"In this lab, we will explore various JavaScript concepts through a series of programming exercises. These exercises are designed to help you develop your skills in JavaScript programming, including data types, functions, loops, and more. By the end of the lab, you will have a solid understanding of how to use JavaScript to create dynamic and interactive web pages.","steps":[{"title":"Random Integer in Range","body":["How to Generate a Random Integer in a Specified Range Using JavaScript","To generate a random integer in a specified range using JavaScript, follow these steps:","Here's an example code snippet that implements the above steps:","You can then call the randomIntegerInRange() function with the desired minimum and maximum values to generate a random integer within that range. For example:"],"code":[{"lang":"js","text":"const randomIntegerInRange = (min, max) =>\n  Math.floor(Math.random() * (max - min + 1)) + min;"},{"lang":"js","text":"randomIntegerInRange(0, 5); // 2"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomIntegerInRange(0, 5); // 2"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-number-in-range":{"intro":"In this lab, we will explore the concept of creating a random number generator in JavaScript. We will use the Math.random() method to generate a random value and map it to a desired range using multiplication. By the end of this lab, you will have a better understanding of how to generate random numbers in JavaScript and how to use them in your projects.","steps":[{"title":"Random Number in Range","body":["How to Generate a Random Number in a Given Range using JavaScript","To generate a random number in a specified range using JavaScript, follow these steps:","• To use the function, pass in the minimum and maximum values of the desired range as arguments. For example:","By following these steps, you can easily generate a random number in a given range using JavaScript."],"code":[{"lang":"js","text":"const randomNumberInRange = (min, max) => Math.random() * (max - min) + min;"},{"lang":"js","text":"randomNumberInRange(2, 10); // 6.0211363285087005"}]}],"commands":[],"reference":[{"path":"reference.js","text":"randomNumberInRange(2, 10); // 6.0211363285087005"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-generating-range-values-with-javascript-gene":{"intro":"In this lab, we will explore how to create a rangeGenerator function in JavaScript that generates all values in a given range using a specified step. We will use a while loop and the yield keyword to return each value and increment by the specified step. By the end of this lab, you will have a better understanding of how to create custom generators in JavaScript and their practical applications.","steps":[{"title":"Range Generator","body":["• Use a while loop and yield to return each value, starting from start and ending at end. • If you want to use a default step of 1, omit the third argument.","Here's an example of how to use the rangeGenerator function:"],"code":[{"lang":"js","text":"const rangeGenerator = function* (start, end, step = 1) {\n  let i = start;\n  while (i < end) {\n    yield i;\n    i += step;\n  }\n};"},{"lang":"js","text":"for (let i of rangeGenerator(6, 10)) console.log(i);\n// Logs 6, 7, 8, 9"}]}],"commands":[],"reference":[{"path":"reference.js","text":"for (let i of rangeGenerator(6, 10)) console.log(i);\n// Logs 6, 7, 8, 9"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-record-animation-frames":{"intro":"In this lab, we will explore the use of recursion and the Window.requestAnimationFrame() method to create a function that can record animation frames and invoke a provided callback on each frame. We will also learn how to control the recording manually using the start and stop methods of the returned object. This lab will help us understand how to work with animation frames in JavaScript and how to create more efficient and controlled animations.","steps":[{"title":"Record Animation Frames","body":["Guide to Record Animation Frames","To record animation frames, follow the steps below:","Use the following code to record animation frames:"],"code":[{"lang":"js","text":"const recordAnimationFrames = (callback, autoStart = true) => {\n  let running = false,\n    raf;\n  const stop = () => {\n    if (!running) return;\n    running = false;\n    cancelAnimationFrame(raf);\n  };\n  const start = () => {\n    if (running) return;\n    running = true;\n    run();\n  };\n  const run = () => {\n    raf = requestAnimationFrame(() => {\n      callback();\n      if (running) run();\n    });\n  };\n  if (autoStart) start();\n  return { start, stop };\n};"},{"lang":"js","text":"const cb = () => console.log(\"Animation frame fired\");\nconst recorder = recordAnimationFrames(cb);\n// logs 'Animation frame fired' on each animation frame\nrecorder.stop(); // stops logging\nrecorder.start(); // starts again\nconst recorder2 = recordAnimationFrames(cb, false);\n// `start` needs to be explicitly called to begin recording frames"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const cb = () => console.log(\"Animation frame fired\");\nconst recorder = recordAnimationFrames(cb);\n// logs 'Animation frame fired' on each animation frame\nrecorder.stop(); // stops logging\nrecorder.start(); // starts again\nconst recorder2 = recordAnimationFrames(cb, false);\n// `start` needs to be explicitly called to begin recording frames"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-reject-non-matching-values":{"intro":"In this lab, we will explore how to filter an array's values based on a predicate function, returning only values for which the predicate function returns false. We will use Array.prototype.filter() in combination with the predicate function to achieve this. By the end of this lab, you will have a good understanding of how to implement this technique in your JavaScript code.","steps":[{"title":"Reject Non-Matching Values","body":["To filter an array based on a predicate function and return only values for which the predicate function returns false, follow these steps:","• Use Array.prototype.filter() in combination with the predicate function, pred. • The filter method will return only the values for which the predicate function returns false. • To reject non-matching values, pass the predicate function and the array to the reject() function.","Here are some examples of how to use the reject() function:","By following these steps, you can easily filter an array based on a predicate function and reject non-matching values."],"code":[{"lang":"js","text":"const reject = (pred, array) => array.filter((...args) => !pred(...args));"},{"lang":"js","text":"reject((x) => x % 2 === 0, [1, 2, 3, 4, 5]); // [1, 3, 5]\nreject((word) => word.length > 4, [\"Apple\", \"Pear\", \"Kiwi\", \"Banana\"]);\n// ['Pear', 'Kiwi']"}]}],"commands":[],"reference":[{"path":"reference.js","text":"reject((x) => x % 2 === 0, [1, 2, 3, 4, 5]); // [1, 3, 5]\nreject((word) => word.length > 4, [\"Apple\", \"Pear\", \"Kiwi\", \"Banana\"]);\n// ['Pear', 'Kiwi']"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-removing-accents-in-javascript-strings":{"intro":"In this lab, we will explore how to remove accents from strings using JavaScript. Accented characters can sometimes cause issues when working with strings, such as when comparing or sorting them. By utilizing the normalize() and replace() methods, we can easily remove these accents and ensure consistent string manipulation in our code. Join us as we dive into this useful technique for string handling in JavaScript.","steps":[{"title":"Remove Accents","body":["This function removes accents from strings.","• Use String.prototype.normalize() to convert the string to a normalized Unicode format. • Use String.prototype.replace() to replace diacritical marks in the given Unicode range with empty strings."],"code":[{"lang":"js","text":"const removeAccents = (str) =>\n  str.normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g, \"\");"},{"lang":"js","text":"removeAccents(\"Antoine de Saint-Exupéry\"); // 'Antoine de Saint-Exupery'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"removeAccents(\"Antoine de Saint-Exupéry\"); // 'Antoine de Saint-Exupery'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-remove-matching-elements-from-array":{"intro":"In this lab, we will be exploring how to remove matching elements from an array using JavaScript. We will be using the Array.prototype.filter() method to find the elements that match the given condition and Array.prototype.reduce() method to remove them from the original array. By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Remove Matching Elements From Array","body":["Removing Matching Elements from an Array","To remove specific elements from an array based on a given condition, you can use the remove function. This function mutates the original array by removing elements for which the given function returns false.","Here are the steps to use the remove function:","Here's an example of using the remove function:"],"code":[{"lang":"js","text":"const remove = (arr, func) =>\n  Array.isArray(arr)\n    ? arr.filter(func).reduce((acc, val) => {\n        arr.splice(arr.indexOf(val), 1);\n        return acc.concat(val);\n      }, [])\n    : [];"},{"lang":"js","text":"remove([1, 2, 3, 4], (n) => n % 2 === 0); // [2, 4]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"remove([1, 2, 3, 4], (n) => n % 2 === 0); // [2, 4]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-remove-non-ascii-characters":{"intro":"In this lab, we will explore the world of JavaScript programming and learn how to use it to build dynamic and interactive web applications. Through a series of hands-on exercises and coding challenges, we will cover topics such as variables, data types, functions, control flow, and more. By the end of the lab, you will have a solid understanding of the fundamentals of JavaScript programming and be ready to take your skills to the next level.","steps":[{"title":"Remove Non ASCII Characters","body":["How to Remove Non-ASCII Characters in JavaScript","To remove non-printable ASCII characters in JavaScript, you can follow these steps:","This will return the string with all non-ASCII characters removed."],"code":[{"lang":"js","text":"const removeNonASCII = (str) => str.replace(/[^\\x20-\\x7E]/g, \"\");\n\nremoveNonASCII(\"äÄçÇéÉêlorem-ipsumöÖÐþúÚ\"); // 'lorem-ipsum'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const removeNonASCII = (str) => str.replace(/[^\\x20-\\x7E]/g, \"\");\n\nremoveNonASCII(\"äÄçÇéÉêlorem-ipsumöÖÐþúÚ\"); // 'lorem-ipsum'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-string-manipulation-with-javascript":{"intro":"In this lab, we will explore the concept of string manipulation in JavaScript. Specifically, we will focus on removing whitespaces from strings using regular expressions. Through a series of exercises and examples, we will gain a deeper understanding of how to use the String.prototype.replace() method to remove whitespace characters and create cleaner, more manageable strings.","steps":[{"title":"Remove Whitespaces","body":["Function to Remove Whitespaces","To remove whitespaces from a string, use the following function.","• Use String.prototype.replace() with a regular expression to replace all occurrences of whitespace characters with an empty string.","• /\\s+/g breaks down as: • \\s: Matches any whitespace character (spaces, tabs, line breaks) • +: Matches one or more occurrences of the previous character • /g: Global flag - matches all occurrences in the string, not just the first one"],"code":[{"lang":"js","text":"const removeWhitespace = (str) => str.replace(/\\s+/g, \"\");"},{"lang":"js","text":"removeWhitespace(\"Lorem ipsum.\\n Dolor sit amet. \");\n// 'Loremipsum.Dolorsitamet.'\n\n// More examples:\nremoveWhitespace(\"Hello    World\"); // \"HelloWorld\"\nremoveWhitespace(\"Tab\\there\\nNew line\"); // \"TabhereNewline\""}]}],"commands":[],"reference":[{"path":"reference.js","text":"removeWhitespace(\"Lorem ipsum.\\n Dolor sit amet. \");\n// 'Loremipsum.Dolorsitamet.'\n\n// More examples:\nremoveWhitespace(\"Hello    World\"); // \"HelloWorld\"\nremoveWhitespace(\"Tab\\there\\nNew line\"); // \"TabhereNewline\""}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-rename-object-keys":{"intro":"In this lab, we will explore how to rename object keys in JavaScript. The lab will cover how to use Object.keys() and Array.prototype.reduce() in combination with the spread operator to get an object's keys and rename them according to a provided mapping. By the end of the lab, you will have a solid understanding of how to effectively rename object keys in your JavaScript code.","steps":[{"title":"Rename Object Keys","body":["How to Rename Object Keys in JavaScript","To rename multiple object keys with the values provided, you can use the renameKeys function. Here are the steps you need to follow:","Here's an example of how to use the renameKeys function:"],"code":[{"lang":"js","text":"const renameKeys = (keysMap, obj) =>\n  Object.keys(obj).reduce(\n    (acc, key) => ({\n      ...acc,\n      ...{ [keysMap[key] || key]: obj[key] }\n    }),\n    {}\n  );\n\nconst obj = { name: \"Bobo\", job: \"Front-End Master\", shoeSize: 100 };\nrenameKeys({ name: \"firstName\", job: \"passion\" }, obj);\n// { firstName: 'Bobo', passion: 'Front-End Master', shoeSize: 100 }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const renameKeys = (keysMap, obj) =>\n  Object.keys(obj).reduce(\n    (acc, key) => ({\n      ...acc,\n      ...{ [keysMap[key] || key]: obj[key] }\n    }),\n    {}\n  );\n\nconst obj = { name: \"Bobo\", job: \"Front-End Master\", shoeSize: 100 };\nrenameKeys({ name: \"firstName\", job: \"passion\" }, obj);\n// { firstName: 'Bobo', passion: 'Front-End Master', shoeSize: 100 }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-replace-last-occurrence-in-string":{"intro":"In this lab, we will explore the replaceLast function in JavaScript, which replaces the last occurrence of a pattern in a given string with a specified replacement. This lab will guide you through the implementation of the replaceLast function, which will enable you to manipulate strings in a more efficient and flexible manner. By the end of this lab, you will have a solid understanding of how to replace the last occurrence of a pattern in a string and will be able to apply this knowledge to your future programming projects.","steps":[{"title":"Understanding the Problem and Setting Up","body":["Understanding the Problem and Setting Up","Before we start coding, let us understand what our replaceLast function should do:","• Accept three parameters: • str: The input string to modify • pattern: The substring or regular expression to search for • replacement: The string to replace the last occurrence with","• Return a new string with the last occurrence of the pattern replaced."],"code":[{"lang":"javascript","text":"// Function to replace the last occurrence of a pattern in a string\nfunction replaceLast(str, pattern, replacement) {\n  // Our implementation will go here\n  return str;\n}\n\n// We will add test cases here later"},{"lang":"javascript","text":"// Example usage\nconsole.log(replaceLast(\"Hello world world\", \"world\", \"JavaScript\"));"},{"lang":"bash","text":"cd ~/project/replace-last"}]},{"title":"Implementing the Core Function Logic","body":["Implementing the Core Function Logic","Now that we understand the problem, let us implement the core functionality of our replaceLast function. We will focus on handling string patterns first, then tackle regular expressions in the next step.","When the pattern is a string, we can use the lastIndexOf method to find the position of the last occurrence. Once we know this position, we can use the slice method to rebuild the string with the replacement inserted.","Update your replaceLast function with the following implementation:"],"code":[{"lang":"javascript","text":"function replaceLast(str, pattern, replacement) {\n  // Ensure inputs are valid\n  if (typeof str !== \"string\") {\n    return str;\n  }\n\n  if (typeof pattern === \"string\") {\n    // Find the position of the last occurrence\n    const lastIndex = str.lastIndexOf(pattern);\n\n    // If pattern not found, return original string\n    if (lastIndex === -1) {\n      return str;\n    }\n\n    // Rebuild the string with the replacement\n    const before = str.slice(0, lastIndex);\n    const after = str.slice(lastIndex + pattern.length);\n    return before + replacement + after;\n  }\n\n  // We'll handle regex patterns in the next step\n  return str;\n}"},{"lang":"javascript","text":"// Test cases for string patterns\nconsole.log(replaceLast(\"Hello world world\", \"world\", \"JavaScript\")); // Should output: \"Hello world JavaScript\"\nconsole.log(replaceLast(\"abcabcabc\", \"abc\", \"123\")); // Should output: \"abcabc123\"\nconsole.log(replaceLast(\"abcdef\", \"xyz\", \"123\")); // Should output: \"abcdef\" (pattern not found)"},{"lang":"bash","text":"node replaceLast.js"}]},{"title":"Handling Regular Expression Patterns","body":["Handling Regular Expression Patterns","Now let us enhance our function to handle regular expression patterns. When the pattern is a regular expression, we need to:","• Find all matches in the string • Get the last match • Replace that last match with the replacement string","Update your replaceLast function to handle regular expression patterns:"],"code":[{"lang":"javascript","text":"function replaceLast(str, pattern, replacement) {\n  // Ensure inputs are valid\n  if (typeof str !== \"string\") {\n    return str;\n  }\n\n  // Handle string patterns\n  if (typeof pattern === \"string\") {\n    const lastIndex = str.lastIndexOf(pattern);\n    if (lastIndex === -1) {\n      return str;\n    }\n    const before = str.slice(0, lastIndex);\n    const after = str.slice(lastIndex + pattern.length);\n    return before + replacement + after;\n  }\n\n  // Handle regular expression patterns\n  if (pattern instanceof RegExp) {\n    // Create a new RegExp with global flag to find all matches\n    const globalRegex = new RegExp(pattern.source, \"g\");\n\n    // Find all matches\n    const matches = str.match(globalRegex);\n\n    // If no matches, return original string\n    if (!matches || matches.length === 0) {\n      return str;\n    }\n\n    // Get the last match\n    const lastMatch = matches[matches.length - 1];\n\n    // Find the position of the last match\n    const lastIndex = str.lastIndexOf(lastMatch);\n\n    // Rebuild the string with the replacement\n    const before = str.slice(0, lastIndex);\n    const after = str.slice(lastIndex + lastMatch.length);\n    return before + replacement + after;\n  }\n\n  // If pattern is neither string nor RegExp, return original string\n  return str;\n}"},{"lang":"javascript","text":"// Test cases for string patterns\nconsole.log(replaceLast(\"Hello world world\", \"world\", \"JavaScript\")); // Should output: \"Hello world JavaScript\"\nconsole.log(replaceLast(\"abcabcabc\", \"abc\", \"123\")); // Should output: \"abcabc123\"\nconsole.log(replaceLast(\"abcdef\", \"xyz\", \"123\")); // Should output: \"abcdef\" (pattern not found)\n\n// Test cases for regular expression patterns\nconsole.log(replaceLast(\"Hello world world\", /world/, \"JavaScript\")); // Should output: \"Hello world JavaScript\"\nconsole.log(replaceLast(\"123 456 789\", /\\d+/, \"numbers\")); // Should output: \"123 456 numbers\"\nconsole.log(replaceLast(\"abcdef\", /xyz/, \"123\")); // Should output: \"abcdef\" (pattern not found)"},{"lang":"bash","text":"node replaceLast.js"}]},{"title":"Optimizing the Function and Testing Edge Cases","body":["Optimizing the Function and Testing Edge Cases","Our function works for basic cases, but let us optimize it and handle some edge cases:","• We should check if the input string is empty • We can simplify our regex handling • We should handle cases where the replacement is not a string","Update your replaceLast function with these optimizations:"],"code":[{"lang":"javascript","text":"function replaceLast(str, pattern, replacement) {\n  // Ensure str is a string\n  if (typeof str !== \"string\") {\n    return str;\n  }\n\n  // If str is empty or pattern is not provided, return original string\n  if (str === \"\" || pattern === undefined) {\n    return str;\n  }\n\n  // Ensure replacement is a string\n  if (replacement === undefined) {\n    replacement = \"\";\n  } else if (typeof replacement !== \"string\") {\n    replacement = String(replacement);\n  }\n\n  // Handle string patterns\n  if (typeof pattern === \"string\") {\n    const lastIndex = str.lastIndexOf(pattern);\n    if (lastIndex === -1) {\n      return str;\n    }\n    return (\n      str.slice(0, lastIndex) +\n      replacement +\n      str.slice(lastIndex + pattern.length)\n    );\n  }\n\n  // Handle regular expression patterns\n  if (pattern instanceof RegExp) {\n    // Create a global version of the regex to find all matches\n    const globalRegex = new RegExp(\n      pattern.source,\n      \"g\" + (pattern.ignoreCase ? \"i\" : \"\") + (pattern.multiline ? \"m\" : \"\")\n    );\n\n    // Find all matches\n    const matches = str.match(globalRegex);\n\n    // If no matches, return original string\n    if (!matches || matches.length === 0) {\n      return str;\n    }\n\n    // Get the last match"},{"lang":"javascript","text":"// Test cases for string patterns\nconsole.log(replaceLast(\"Hello world world\", \"world\", \"JavaScript\")); // Should output: \"Hello world JavaScript\"\nconsole.log(replaceLast(\"abcabcabc\", \"abc\", \"123\")); // Should output: \"abcabc123\"\nconsole.log(replaceLast(\"abcdef\", \"xyz\", \"123\")); // Should output: \"abcdef\" (pattern not found)\n\n// Test cases for regular expression patterns\nconsole.log(replaceLast(\"Hello world world\", /world/, \"JavaScript\")); // Should output: \"Hello world JavaScript\"\nconsole.log(replaceLast(\"123 456 789\", /\\d+/, \"numbers\")); // Should output: \"123 456 numbers\"\nconsole.log(replaceLast(\"abcdef\", /xyz/, \"123\")); // Should output: \"abcdef\" (pattern not found)\n\n// Edge cases\nconsole.log(replaceLast(\"\", \"abc\", \"123\")); // Should output: \"\" (empty string)\nconsole.log(replaceLast(\"abcdef\", \"\", \"123\")); // Should output: \"abcde123f\" (empty pattern)\nconsole.log(replaceLast(\"abcdef\", \"def\", \"\")); // Should output: \"abc\" (empty replacement)\nconsole.log(replaceLast(\"AbCdEf\", /[a-z]/, \"X\")); // Should output: \"AbCdEX\" (case-sensitive regex)\nconsole.log(replaceLast(\"AbCdEf\", /[a-z]/i, \"X\")); // Should output: \"AbCdEX\" (case-insensitive regex)"},{"lang":"bash","text":"node replaceLast.js"}]},{"title":"Creating a Module and Using the Function","body":["Creating a Module and Using the Function","In this final step, we will convert our function into a proper JavaScript module that can be imported and used in other files. This is a common practice in real-world JavaScript development.","First, let us create a module file for our function. Create a new file called replaceLastModule.js in the replace-last directory:","Now, let us create another file to use our module. Create a new file called app.js in the replace-last directory:"],"code":[{"lang":"javascript","text":"/**\n * Replaces the last occurrence of a pattern in a string.\n *\n * @param {string} str - The input string.\n * @param {string|RegExp} pattern - The pattern to replace (string or RegExp).\n * @param {string} replacement - The replacement string.\n * @returns {string} - The string with the last occurrence replaced.\n */\nfunction replaceLast(str, pattern, replacement) {\n  // Ensure str is a string\n  if (typeof str !== \"string\") {\n    return str;\n  }\n\n  // If str is empty or pattern is not provided, return original string\n  if (str === \"\" || pattern === undefined) {\n    return str;\n  }\n\n  // Ensure replacement is a string\n  if (replacement === undefined) {\n    replacement = \"\";\n  } else if (typeof replacement !== \"string\") {\n    replacement = String(replacement);\n  }\n\n  // Handle string patterns\n  if (typeof pattern === \"string\") {\n    const lastIndex = str.lastIndexOf(pattern);\n    if (lastIndex === -1) {\n      return str;\n    }\n    return (\n      str.slice(0, lastIndex) +\n      replacement +\n      str.slice(lastIndex + pattern.length)\n    );\n  }\n\n  // Handle regular expression patterns\n  if (pattern instanceof RegExp) {\n    // Create a global version of the regex to find all matches\n    const globalRegex = new RegExp(\n      pattern.source,\n      \"g\" + (pattern.ignoreCase ? \"i\" : \"\") + (pattern.multiline ? \"m\" : \"\")\n    );\n\n    // Find all matches"},{"lang":"javascript","text":"// Import the replaceLast function\nconst replaceLast = require(\"./replaceLastModule\");\n\n// Examples of using the replaceLast function\nconsole.log(\n  \"Example 1:\",\n  replaceLast(\"Hello world world\", \"world\", \"JavaScript\")\n);\nconsole.log(\"Example 2:\", replaceLast(\"abcabcabc\", \"abc\", \"123\"));\nconsole.log(\"Example 3:\", replaceLast(\"file.txt.backup.txt\", \".txt\", \".md\"));\nconsole.log(\"Example 4:\", replaceLast(\"123 456 789\", /\\d+/, \"numbers\"));\nconsole.log(\n  \"Example 5:\",\n  replaceLast(\"The fox jumped over the lazy dog\", /[a-z]+/i, \"cat\")\n);\n\n// Practical examples\nconst filePath = \"/path/to/my/file.txt\";\nconsole.log(\"File with new extension:\", replaceLast(filePath, \".txt\", \".md\"));\n\nconst url = \"https://example.com/products/category/item?color=red\";\nconsole.log(\"URL with updated parameter:\", replaceLast(url, \"red\", \"blue\"));\n\nconst htmlTag = \"<div class='container'><p>Text</p></div>\";\nconsole.log(\n  \"HTML with replaced tag:\",\n  replaceLast(htmlTag, /<\\/?\\w+>/g, \"<span>\")\n);"},{"lang":"bash","text":"node app.js"}]}],"commands":["cd ~/project/replace-last","node replaceLast.js","node app.js"],"reference":[],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-replace-or-append-array-value":{"intro":"In this lab, we will work on a JavaScript programming exercise that involves replacing or appending values in an array based on a comparison function. Through this exercise, you will learn how to use the spread operator, Array.prototype.findIndex(), Array.prototype.push(), and Array.prototype.splice() to manipulate arrays in JavaScript. This lab will help you improve your skills in working with arrays and functions in JavaScript.","steps":[{"title":"Replace or Append Array Value","body":["How to Replace or Append Array Value","To replace an item in an array or append it if it doesn't exist, follow these steps:","• Use the spread operator (...) to create a shallow copy of the array. • Use Array.prototype.findIndex() to find the index of the first element that satisfies the provided comparison function compFn. • If no such element is found, use Array.prototype.push() to append the new value to the array. • Otherwise, use Array.prototype.splice() to replace the value at the found index with the new value.","Here is an example of how to implement this functionality:"],"code":[{"lang":"js","text":"const replaceOrAppend = (arr, val, compFn) => {\n  const res = [...arr];\n  const i = arr.findIndex((v) => compFn(v, val));\n  if (i === -1) res.push(val);\n  else res.splice(i, 1, val);\n  return res;\n};"},{"lang":"js","text":"const people = [\n  { name: \"John\", age: 30 },\n  { name: \"Jane\", age: 28 }\n];\nconst jane = { name: \"Jane\", age: 29 };\nconst jack = { name: \"Jack\", age: 28 };\nreplaceOrAppend(people, jane, (a, b) => a.name === b.name);\n// [ { name: 'John', age: 30 }, { name: 'Jane', age: 29 } ]\nreplaceOrAppend(people, jack, (a, b) => a.name === b.name);\n// [\n//   { name: 'John', age: 30 },\n//   { name: 'Jane', age: 28 },\n//   { name: 'Jack', age: 28 }\n// ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const people = [\n  { name: \"John\", age: 30 },\n  { name: \"Jane\", age: 28 }\n];\nconst jane = { name: \"Jane\", age: 29 };\nconst jack = { name: \"Jack\", age: 28 };\nreplaceOrAppend(people, jane, (a, b) => a.name === b.name);\n// [ { name: 'John', age: 30 }, { name: 'Jane', age: 29 } ]\nreplaceOrAppend(people, jack, (a, b) => a.name === b.name);\n// [\n//   { name: 'John', age: 30 },\n//   { name: 'Jane', age: 28 },\n//   { name: 'Jack', age: 28 }\n// ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-resolve-promise-after-given-amount-of-time":{"intro":"In this lab, we will learn how to create a promise that resolves to a given value after a specified amount of time using JavaScript. We will use the Promise constructor to create a new promise and the setTimeout() method to delay the resolution of the promise. This skill is essential when working with asynchronous operations in JavaScript.","steps":[{"title":"Resolve Promise After Given Amount of Time","body":["Creating a Promise with a Delay","To create a new promise that resolves after a specific amount of time, follow these steps:","• Use the Promise constructor to create a new promise. • Inside the promise's executor function, use setTimeout() to call the promise's resolve function with the provided value after the specified delay.","Here's an example implementation of resolveAfter():"],"code":[{"lang":"js","text":"const resolveAfter = (value, delay) =>\n  new Promise((resolve) => {\n    setTimeout(() => resolve(value), delay);\n  });"},{"lang":"js","text":"resolveAfter(\"Hello\", 1000);\n// Returns a promise that resolves to 'Hello' after 1s"}]}],"commands":[],"reference":[{"path":"reference.js","text":"resolveAfter(\"Hello\", 1000);\n// Returns a promise that resolves to 'Hello' after 1s"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-composing-functions-left-to-right":{"intro":"In this lab, we will explore the concept of function composition in JavaScript. Specifically, we will focus on the composeRight function, which allows us to combine multiple functions into a single function that is executed from left to right. Through practical examples, we will see how function composition can simplify our code and make it more modular.","steps":[{"title":"Reverse Compose Functions","body":["Reversing Function Composition","Here's how to perform left-to-right function composition:","• Use Array.prototype.reduce() method to perform left-to-right function composition. • The first (leftmost) function can accept one or more arguments, while the remaining functions must be unary."],"code":[{"lang":"js","text":"const composeRight = (...fns) =>\n  fns.reduce(\n    (f, g) =>\n      (...args) =>\n        g(f(...args))\n  );"},{"lang":"js","text":"const add = (x, y) => x + y;\nconst square = (x) => x * x;\nconst addAndSquare = composeRight(add, square);\naddAndSquare(1, 2); // 9"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const add = (x, y) => x + y;\nconst square = (x) => x * x;\nconst addAndSquare = composeRight(add, square);\naddAndSquare(1, 2); // 9"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-iterate-over-object-s-own-properties-in-reve":{"intro":"In this lab, we will explore how to iterate over an object's own properties in reverse order using JavaScript. We will use built-in methods such as Object.keys() and Array.prototype.reverse() to achieve this. By the end of this lab, you will have a better understanding of how to work with objects in JavaScript and how to manipulate their properties.","steps":[{"title":"Iterate Over Object's Own Properties in Reverse","body":["Here's how to iterate over an object's own properties in reverse","To iterate over an object's own properties in reverse order and run a callback for each one, follow these steps:","You can use this function with any object and callback function. For example, to log the values of { foo: 'bar', a: 1 } in reverse order, you can use the following code:"],"code":[{"lang":"js","text":"const forOwnRight = (obj, fn) =>\n  Object.keys(obj)\n    .reverse()\n    .forEach((key) => fn(obj[key], key, obj));"},{"lang":"js","text":"forOwnRight({ foo: \"bar\", a: 1 }, (v) => console.log(v)); // 1, 'bar'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"forOwnRight({ foo: \"bar\", a: 1 }, (v) => console.log(v)); // 1, 'bar'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-reversing-numbers-in-javascript":{"intro":"In this lab, we will explore the concept of reversing a number in JavaScript. We will learn how to use built-in methods such as split(), reverse(), and join() to achieve this task. By the end of this lab, you will have a deeper understanding of how to manipulate numbers in JavaScript.","steps":[{"title":"Reverse Number","body":["To reverse a number using JavaScript, you can use the reverseNumber() function with the following steps:","• Convert the number n to a string using Object.prototype.toString(). • Use String.prototype.split(), Array.prototype.reverse() and Array.prototype.join() to get the reversed value of n as a string. • Convert the string back to a number using parseFloat(). • Preserve the sign of the number using Math.sign().","Here's the code for the reverseNumber() function:","You can test the function with these examples:"],"code":[{"lang":"js","text":"const reverseNumber = (n) =>\n  parseFloat(`${n}`.split(\"\").reverse().join(\"\")) * Math.sign(n);"},{"lang":"js","text":"reverseNumber(981); // 189\nreverseNumber(-500); // -5\nreverseNumber(73.6); // 6.37\nreverseNumber(-5.23); // -32.5"}]}],"commands":[],"reference":[{"path":"reference.js","text":"reverseNumber(981); // 189\nreverseNumber(-500); // -5\nreverseNumber(73.6); // 6.37\nreverseNumber(-5.23); // -32.5"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-rgb-to-hexadecimal-color-conversion-in-javas":{"intro":"In this lab, we will be exploring the process of converting RGB values to hexadecimal color codes in JavaScript. We will be using bitwise left-shift operator and Number.prototype.toString() to convert the given RGB parameters to a 6-digit hexadecimal value using String.prototype.padStart(). This lab will help you understand the conversion process and give you hands-on experience with the implementation of the algorithm in JavaScript.","steps":[{"title":"RGB to Hex","body":["To convert RGB values to a hexadecimal color code:","• Call the function with the RGB values as arguments to get a 6-digit hexadecimal value."],"code":[{"lang":"js","text":"const RGBToHex = (r, g, b) =>\n  ((r << 16) + (g << 8) + b).toString(16).padStart(6, \"0\");"},{"lang":"js","text":"RGBToHex(255, 165, 1); // 'ffa501'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"RGBToHex(255, 165, 1); // 'ffa501'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-basics-through-hands-on":{"intro":"In this lab, we will explore the fundamentals of JavaScript programming language. The lab is designed to help participants gain a solid understanding of the basics of JavaScript, including variables, data types, control structures, functions, and more. Through a series of hands-on exercises and examples, participants will learn how to write code in JavaScript and build simple programs. This lab is suitable for beginners with little to no prior programming experience.","steps":[{"title":"RGB to HSB","body":["To convert a RGB color tuple to HSB format, you can follow these steps:","• H: [0, 360] • S: [0, 100] • B: [0, 100]","Here is the function in JavaScript:","You can call the function like this:"],"code":[{"lang":"js","text":"const RGBToHSB = (r, g, b) => {\n  r /= 255;\n  g /= 255;\n  b /= 255;\n  const v = Math.max(r, g, b),\n    n = v - Math.min(r, g, b);\n  const h =\n    n === 0\n      ? 0\n      : n && v === r\n        ? (g - b) / n\n        : v === g\n          ? 2 + (b - r) / n\n          : 4 + (r - g) / n;\n  return [60 * (h < 0 ? h + 6 : h), v && (n / v) * 100, v * 100];\n};"},{"lang":"js","text":"RGBToHSB(252, 111, 48);\n// [18.529411764705856, 80.95238095238095, 98.82352941176471]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"RGBToHSB(252, 111, 48);\n// [18.529411764705856, 80.95238095238095, 98.82352941176471]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-rgb-to-hsl-color-conversion":{"intro":"In this lab, we will explore the conversion of RGB color tuples to the HSL format. We will use the RGB to HSL conversion formula and implement it using JavaScript. By the end of this lab, you will have a better understanding of how to convert RGB colors to the HSL format and manipulate color values in your projects.","steps":[{"title":"RGB to HSL","body":["To convert an RGB color tuple to HSL format, follow these steps:","Here is an example of the RGBToHSL function in JavaScript:","Here is an example of how to use the RGBToHSL function:"],"code":[{"lang":"js","text":"const RGBToHSL = (r, g, b) => {\n  r /= 255;\n  g /= 255;\n  b /= 255;\n  const l = Math.max(r, g, b);\n  const s = l - Math.min(r, g, b);\n  const h = s\n    ? l === r\n      ? (g - b) / s\n      : l === g\n        ? 2 + (b - r) / s\n        : 4 + (r - g) / s\n    : 0;\n  return [\n    60 * h < 0 ? 60 * h + 360 : 60 * h,\n    100 * (s ? (l <= 0.5 ? s / (2 * l - s) : s / (2 - (2 * l - s))) : 0),\n    (100 * (2 * l - s)) / 2\n  ];\n};"},{"lang":"js","text":"RGBToHSL(45, 23, 11); // [21.17647, 60.71428, 10.98039]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"RGBToHSL(45, 23, 11); // [21.17647, 60.71428, 10.98039]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-right-substring-generator":{"intro":"In this lab, we will be exploring the concept of substring generation in JavaScript. We will focus on generating right substrings of a given string using the for...in loop and String.prototype.slice() method. By the end of this lab, you will have a better understanding of how to manipulate strings in JavaScript and generate substrings for various use cases.","steps":[{"title":"Right Substring Generator","body":["To generate all right substrings of a given string, follow these steps:"],"code":[{"lang":"js","text":"const rightSubstrGenerator = function* (str) {\n  if (!str.length) return;\n  for (let i in str) yield str.slice(-i - 1);\n};"},{"lang":"js","text":"[...rightSubstrGenerator(\"hello\")];\n// [ 'o', 'lo', 'llo', 'ello', 'hello' ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"[...rightSubstrGenerator(\"hello\")];\n// [ 'o', 'lo', 'llo', 'ello', 'hello' ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-round-number-to-given-precision":{"intro":"In this lab, we will explore how to round numbers to a given precision using JavaScript. We will learn how to use the Math.round() method and template literals to round a number to a specified number of digits or to an integer value. This knowledge will be useful in situations where we need to display numbers in a more readable format, such as dealing with currency or measurements.","steps":[{"title":"Round Number to Given Precision","body":["Here's how to round a number to a given precision in JavaScript:"],"code":[{"lang":"text","text":"const round = (n, decimals = 0) =>\n  Number(`${Math.round(`${n}e${decimals}`)}e-${decimals}`);"}]}],"commands":[],"reference":[{"path":"reference.txt","text":"const round = (n, decimals = 0) =>\n  Number(`${Math.round(`${n}e${decimals}`)}e-${decimals}`);"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-run-function-asynchronously":{"intro":"In this lab, we will learn how to execute long-running functions asynchronously by using a Web Worker. The purpose of the lab is to teach developers how to run functions in a separate thread, allowing them to avoid blocking the UI while the function is executing. The lab provides a practical example of how to create a Web Worker and use it to run a function.","steps":[{"title":"Run Function Asynchronously","body":["Asynchronous Function Execution Using Web Workers","To execute a function without blocking the UI, use a Web Worker to run the function in a separate thread. Here's how:","• Create a Worker using a Blob object URL, with the contents being the stringified version of the function to be executed. • Immediately post the return value of calling the function back. • Return a Promise, listening for onmessage and onerror events and resolving the data posted back from the worker, or throwing an error.","Note that the function supplied to runAsync should not use closures because everything gets stringified and becomes literal. Therefore, all variables and functions must be defined inside. Here are some examples:"],"code":[{"lang":"js","text":"const runAsync = (fn) => {\n  const worker = new Worker(\n    URL.createObjectURL(new Blob([`postMessage((${fn})());`]), {\n      type: \"application/javascript; charset=utf-8\"\n    })\n  );\n  return new Promise((resolve, reject) => {\n    worker.onmessage = ({ data }) => {\n      resolve(data);\n      worker.terminate();\n    };\n    worker.onerror = (error) => {\n      reject(error);\n      worker.terminate();\n    };\n  });\n};"},{"lang":"js","text":"const longRunningFunction = () => {\n  let result = 0;\n  for (let i = 0; i < 1000; i++)\n    for (let j = 0; j < 700; j++)\n      for (let k = 0; k < 300; k++) result = result + i + j + k;\n\n  return result;\n};\n\nrunAsync(longRunningFunction).then(console.log); // 209685000000\nrunAsync(() => 10 ** 3).then(console.log); // 1000\nlet outsideVariable = 50;\nrunAsync(() => typeof outsideVariable).then(console.log); // 'undefined'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const longRunningFunction = () => {\n  let result = 0;\n  for (let i = 0; i < 1000; i++)\n    for (let j = 0; j < 700; j++)\n      for (let k = 0; k < 300; k++) result = result + i + j + k;\n\n  return result;\n};\n\nrunAsync(longRunningFunction).then(console.log); // 209685000000\nrunAsync(() => 10 ** 3).then(console.log); // 1000\nlet outsideVariable = 50;\nrunAsync(() => typeof outsideVariable).then(console.log); // 'undefined'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-serializing-cookies-in-javascript":{"intro":"In this lab, we will be exploring the concept of serializing cookies in JavaScript. Cookies are an essential part of web development, and it is crucial to understand how to handle them properly. By the end of this lab, you will be able to serialize a cookie name-value pair into a Set-Cookie header string using template literals and encodeURIComponent().","steps":[{"title":"Serialize Cookie","body":["• Use template literals and encodeURIComponent() to create the appropriate string. • Implement the serializeCookie function by passing in the name and val parameters. • The function will return a string that is properly serialized.","Here is an example of how to use the serializeCookie function:","In this example, the serializeCookie function takes in foo as the cookie name and bar as the cookie value, and returns a serialized cookie string of foo=bar."],"code":[{"lang":"js","text":"const serializeCookie = (name, val) =>\n  `${encodeURIComponent(name)}=${encodeURIComponent(val)}`;\n\nserializeCookie(\"foo\", \"bar\"); // 'foo=bar'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const serializeCookie = (name, val) =>\n  `${encodeURIComponent(name)}=${encodeURIComponent(val)}`;\n\nserializeCookie(\"foo\", \"bar\"); // 'foo=bar'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
